def parse() -> dict[str, list[tuple[str, int, int]]]:
    out = {}
    for make, line in _RAW.items():
        items = []
        for part in line.split(";"):
            name, yrs = part.rsplit(":", 1)
            y0, y1 = (int(x) for x in yrs.split("-"))
            if y1 < MIN_YEAR:
                continue
            items.append((name.strip(), max(y0, MIN_YEAR), y1))
        out[make] = sorted(set(items))
    return out
